  ctx.beginPath();
  ctx.moveTo(cx, cy);
  ctx.lineTo(cx + Math.cos(minA) * r * 0.7, cy + Math.sin(minA) * r * 0.7);
  ctx.strokeStyle = '#eee';
  ctx.lineWidth = 4 * dpr;
  ctx.stroke();

  const hourA = ((hours + minutes / 60) * 30 - 90) * Math.PI / 180;
  ctx.beginPath();
